{"query":"
  query GetFooterLangReference($preview: Boolean) {
    countryListReference(slug: "country-region-mapping-all", preview: $preview) {
      countryList
    }
    languagesListReference(slug: "privacy-center-list", preview: $preview) {
      languagesList
    }
  }
","variables":{"preview":false}}

{"query":"
  query GetFooterContent($slug: ID!, $locale: String, $preview: Boolean) {
    footer(slug: $slug, locale: $locale, preview: $preview) {
      logo {
        ... on Logo {
          logoCta
          shouldShowLogo
          logo {
            description
            name
            urls {
              boei18n
              gcp
              ie
              sg
              ttp
              ttp2
              va
            }
          }
        }
      }
      navigation {
        ... on NavSection {
          navTitle
          navTitleFontWeight
          navTitleFontColor
          navTitleFontSize
          shouldShowOnMobile
          mobileNavTitle
          navTabs {
            ... on Link {
              id
              fontColor
              fontSize
              fontWeight
              mobileTitle
              mobileUrl
              openNewTab
              shouldShowOnMobile
              shortTitle
              includeByRegion
              excludeByRegion
              image {
                description
                name
                urls {
                  boei18n
                  gcp
                  ie
                  sg
                  ttp
                  ttp2
                  va
                }
              }
              title
              url
            }
          }
        }
      }
      languageSelector {
        ... on LanguageSelector {
          shouldShow
          showFullName
          showLanguageCode
        }
      }
      sys {
        publishedLanguages
      }
    }
  }
","variables":{"slug":"footer-lang","locale":"fr","preview":false}}
